  + 'import classNames from "classnames";\n'
  + 'import type { ElementContent, Root, RootContent } from "hast";\n'
  + '\n'
  + 'function transformCode(\n'
  + '  node: RootContent,\n'
  + '  opts: {\n'
  + '    withLineNumbers: boolean;\n'
  + '    lineHighlight?: { ge: number; lt: number };\n'
  + '    lineNumberClassName: string;\n'
  + '    lineHighlightClassName: string;\n'
  + '  },\n'
  + '): { lineNumbersChildren: ElementContent[] } | null {\n'
  + '  if (node.type === "element" && node.tagName === "code") {\n'
  + '    let lineNo = 1;\n'
  + '    const lineNumbersChildren = [] as ElementContent[];\n'
  + '    const nodeChildren = [] as ElementContent[];\n'
  + '    node.children.forEach((child) => {\n'
  + '      // Process each line.\n'
  + '      if (\n'
  + '        child.type === "element" &&\n'
  + '        child.tagName === "span" &&\n'
  + '        child.properties.class === "line"\n'
  + '      ) {\n'
  + '        // Check if this line is highlighted.\n'
  + '        let highlighted = false;\n'
  + '        if (opts.lineHighlight != null) {\n'
  + '          if (\n'
  + '            lineNo >= opts.lineHighlight.ge &&\n'
  + '            lineNo < opts.lineHighlight.lt\n'
  + '          ) {\n'
  + '            highlighted = true;\n'
  + '          }\n'
  + '        }\n'
  + '\n'
  + '        // Add a new child for line-numbers.\n'
  + '        lineNumbersChildren.push({\n'
  + '          type: "element",\n'
  + '          tagName: "span",\n'
  + '          properties: {\n'
  + '            class: opts.lineNumberClassName, // styles.codeHighlightLineNumber,\n'
  + '            "data-highlighted": highlighted ? "true" : undefined,\n'
  + '          },\n'
  + '          children: [{ type: "text", value: String(lineNo++) }],\n'
  + '        });\n'
  + '\n'
  + '        // Transform child.\n'
  + '        child.children = [\n'
  + '          JSON.parse(JSON.stringify(child)),\n'
  + '          { type: "text", value: "\\n" },\n'
  + '        ];\n'
  + '        child.tagName = "div";\n'
  + '        child.properties.class = classNames(\n'
  + '          child.properties.class,\n'
  + '          opts.lineHighlightClassName, // styles.codeHighlightLine,\n'
  + '        );\n'
  + '        child.properties["data-highlighted"] = highlighted ? "true" : undefined;\n'
  + '        child.properties["data-with-line-number"] = opts.withLineNumbers\n'
  + '          ? "true"\n'
  + '          : undefined;\n'
  + '\n'
  + '        nodeChildren.push(child);\n'
  + '      }\n'
  + '    });\n'
  + '    node.children = nodeChildren;\n'
  + '\n'
  + '    if (!opts.withLineNumbers) {\n'
  + '      return null;\n'
  + '    }\n'
  + '    return { lineNumbersChildren };\n'
  + '  }\n'
  + '\n'
  + '  return null;\n'
  + '}\n'
  + '\n'
  + 'function transformPre(\n'
  + '  node: RootContent,\n'
  + '  opts: {\n'
  + '    withLineNumbers: boolean;\n'
  + '    lineHighlight?: { ge: number; lt: number };\n'
  + '    lineNumberClassName: string;\n'
  + '    lineHighlightClassName: string;\n'
  + '    preClassName: string;\n'
  + '  },\n'
  + '): { lineNumbersChildren: ElementContent[] } | null {\n'
  + '  if (node.type === "element" && node.tagName === "pre") {\n'
  + '    // Hack to make background-color of <pre> transparent.\n'
  + '    const originalStyle = node.properties.style;\n'
  + '    if (typeof originalStyle === "string") {\n'
  + '      let newStyle = "";\n'
  + '      originalStyle.split(";").forEach((style) => {\n'
  + '        const [key, value] = style.split(":").map((s) => s.trim());\n'
  + '        if (key && value) {\n'
  + '          if (key === "background-color") {\n'
  + '            newStyle += `${key}:transparent;`;\n'
  + '          } else {\n'
  + '            newStyle += `${key}:${value};`;\n'
  + '          }\n'
  + '        }\n'
  + '      });\n'
  + '      node.properties.style = newStyle;\n'
  + '    }\n'
  + '\n'
  + '    // Add class.\n'
  + '    node.properties.class = classNames(\n'
  + '      node.properties.class,\n'
  + '      opts.preClassName, // styles.codeHighlightPre,\n'
  + '    );\n'
  + '\n'
  + '    // Transform <code>.\n'
  + '    let res = null;\n'
  + '    node.children.forEach((child) => {\n'
  + '      res = transformCode(child, opts);\n'
  + '    });\n'
  + '    return res;\n'
  + '  }\n'
  + '\n'
  + '  return null;\n'
  + '}\n'
  + '\n'
  + 'function transformRoot(\n'
  + '  node: Root,\n'
